/*!40000 ALTER TABLE `category` DISABLE KEYS */;
INSERT INTO `category` VALUES (1,1,'work_integrated_applied','Work-Integrated and Applied Learning','An educational approach that explicitly merges theory with real-world practice and embeds authentic industry, workplace, or community-relevant work and tasks into a unit of study.'),(2,1,'simulation','Simulation','An instructional method that recreates or mimics real-world scenarios, environments, or processes so learners can practise skills and make decisions safely.'),(3,1,'case_based','Case-Based Learning','An active teaching method in which students use real-world scenarios and case studies to build critical-thinking and problem-solving skills.'),(4,1,'project_problem_based','Project- and Problem-Based Learning','Learning focused on real-world problems and challenges using problem-solving, decision-making, investigative, and self-directed learning skills.'),(5,1,'community_learning','Community Learning','Learning undertaken together with or for communities, including service-learning, field studies, and professional communities of practice.'),(6,1,'entrepreneurial_learning','Entrepreneurial Learning','Learning that develops the knowledge, skills, and mindset to recognise opportunities, turn ideas into action, and manage new ventures under uncertainty.'),(7,1,'technology_mediated_learning','Technology-Mediated Learning','An instructional environment in which digital devices, networks, or specialised technologies mediate access to content and interaction during learning.'),(8,1,'hybrid_learning','Hybrid Learning','An education model that mixes face-to-face classroom teaching with online digital instruction.');
/*!40000 ALTER TABLE `category` ENABLE KEYS */;
UNLOCK TABLES;

