DROP TABLE IF EXISTS `item_category_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_category_result` (
  `result_id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `extraction_id` bigint NOT NULL,
  `item_id` bigint NOT NULL,
  `ruleset_id` bigint NOT NULL,
  `taxonomy_id` bigint NOT NULL,
  `category_id` bigint NOT NULL,
  `score` decimal(12,2) NOT NULL,
  `decision` enum('positive','review','no_match') NOT NULL,
  `confidence_band` enum('high','moderate','review','none') NOT NULL,
  `manual_review_required` tinyint(1) NOT NULL,
  PRIMARY KEY (`result_id`),
  UNIQUE KEY `run_id` (`run_id`,`item_id`,`category_id`),
  UNIQUE KEY `result_id` (`result_id`,`ruleset_id`,`category_id`),
  KEY `run_id_2` (`run_id`,`extraction_id`,`ruleset_id`,`taxonomy_id`),
  KEY `item_id` (`item_id`,`extraction_id`),
  KEY `category_id` (`category_id`,`taxonomy_id`),
  CONSTRAINT `item_category_result_ibfk_1` FOREIGN KEY (`run_id`, `extraction_id`, `ruleset_id`, `taxonomy_id`) REFERENCES `scoring_run` (`run_id`, `extraction_id`, `ruleset_id`, `taxonomy_id`),
  CONSTRAINT `item_category_result_ibfk_2` FOREIGN KEY (`item_id`, `extraction_id`) REFERENCES `evidence_item` (`item_id`, `extraction_id`),
  CONSTRAINT `item_category_result_ibfk_3` FOREIGN KEY (`category_id`, `taxonomy_id`) REFERENCES `category` (`category_id`, `taxonomy_id`),
  CONSTRAINT `item_category_result_chk_1` CHECK ((`score` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=16937 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

